CREATE TABLE shoe_masters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(50) NOT NULL UNIQUE,name varchar(160) NOT NULL,brand varchar(100) NOT NULL,category varchar(50) NOT NULL,gender varchar(20) NOT NULL DEFAULT 'UNISEX' CHECK(gender IN ('MEN','WOMEN','UNISEX','KIDS')),color varchar(60),size_eu numeric(4,1) NOT NULL CHECK(size_eu BETWEEN 15 AND 55),price numeric(12,2) NOT NULL CHECK(price>=0),stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX shoe_masters_code_idx ON shoe_masters(code); CREATE INDEX shoe_masters_brand_idx ON shoe_masters(brand); CREATE INDEX shoe_masters_category_idx ON shoe_masters(category);
